from openpyxl import load_workbook

wb = load_workbook('nasa_budget_incomplete.xlsx')

# Helper to find header row and col map

def get_col_map(ws, key_header):
    header_row = None
    for r in range(1, 10):
        row_vals = [ws.cell(row=r, column=c).value for c in range(1, ws.max_column+1)]
        if key_header in row_vals:
            header_row = r
            break
    if header_row is None:
        raise ValueError(f'Header row not found for {ws.title}')
    col_map = {}
    for c in range(1, ws.max_column+1):
        val = ws.cell(row=header_row, column=c).value
        if val is not None:
            col_map[str(val)] = c
    return header_row, col_map

# Update Budget by Directorate
ws = wb['Budget by Directorate']
header_row, col_map = get_col_map(ws, 'Fiscal Year')

def find_row_by_year(year):
    for r in range(header_row+1, ws.max_row+1):
        if ws.cell(row=r, column=col_map['Fiscal Year']).value == year:
            return r
    raise ValueError(f'Year {year} not found in {ws.title}')

updates_budget = {
    (2016, 'Total'): 19285,
    (2019, 'Space Operations'): 4639,
    (2020, 'Science'): 7139,
    (2021, 'Exploration'): 6555,
    (2021, 'Total'): 23285,
    (2023, 'Aeronautics'): 936,
}

for (year, col), val in updates_budget.items():
    r = find_row_by_year(year)
    c = col_map[col]
    ws.cell(row=r, column=c, value=val)

# Update YoY Changes (%)
ws = wb['YoY Changes (%)']
header_row, col_map = get_col_map(ws, 'Fiscal Year')

def find_row_by_year_yoy(year):
    for r in range(header_row+1, ws.max_row+1):
        if ws.cell(row=r, column=col_map['Fiscal Year']).value == year:
            return r
    raise ValueError(f'Year {year} not found in {ws.title}')

updates_yoy = {
    (2019, 'Space Technology'): 21.97,
    (2021, 'Science'): 2.27,
    (2021, 'Space Operations'): -0.08,
}

for (year, col), val in updates_yoy.items():
    r = find_row_by_year_yoy(year)
    c = col_map[col]
    ws.cell(row=r, column=c, value=val)

# Update Directorate Shares (%)
ws = wb['Directorate Shares (%)']
header_row, col_map = get_col_map(ws, 'Fiscal Year')

def find_row_by_year_shares(year):
    for r in range(header_row+1, ws.max_row+1):
        if ws.cell(row=r, column=col_map['Fiscal Year']).value == year:
            return r
    raise ValueError(f'Year {year} not found in {ws.title}')

updates_shares = {
    (2021, 'Science'): 31.35,
}

for (year, col), val in updates_shares.items():
    r = find_row_by_year_shares(year)
    c = col_map[col]
    ws.cell(row=r, column=c, value=val)

# Update Growth Analysis
ws = wb['Growth Analysis']
header_row, col_map = get_col_map(ws, 'Metric')

def find_row_by_metric(metric):
    for r in range(header_row+1, ws.max_row+1):
        if ws.cell(row=r, column=col_map['Metric']).value == metric:
            return r
    raise ValueError(f'Metric {metric} not found in {ws.title}')

updates_growth = {
    ('5-Year Change ($M)', 'Science'): 1534,
    ('Avg Annual Budget ($M)', 'Science'): 7610.3,
}

for (metric, col), val in updates_growth.items():
    r = find_row_by_metric(metric)
    c = col_map[col]
    ws.cell(row=r, column=c, value=val)

wb.save('nasa_budget_recovered.xlsx')
print('saved')
